"""Initial PostgreSQL schema (mirrors the desktop SQLite schema at v10).

Same tables, columns, CHECKs and unique rules as ``database/schema.sql`` +
``database/migrations.py`` (v10), with the Postgres-native types:

* ``INTEGER PRIMARY KEY AUTOINCREMENT`` -> ``BIGINT GENERATED BY DEFAULT AS
  IDENTITY`` (BY DEFAULT so a till can later sync rows with their own ids).
* ``REAL`` money -> ``NUMERIC`` (prices/totals 2 decimals, costs 4).
* ``INTEGER 0/1`` flags -> ``BOOLEAN``.
* ISO text timestamps -> ``TIMESTAMPTZ`` (ISO strings still insert fine);
  business dates ('YYYY-MM-DD') -> ``DATE``; ``*_json`` text -> ``JSONB``.
* ``COLLATE NOCASE`` unique indexes -> indexes on ``upper(...)``.
* The append-only triggers raise an exception instead of ``RAISE(ABORT)``.

Revision ID: 0001
Revises:
"""
from alembic import op

revision = "0001"
down_revision = None
branch_labels = None
depends_on = None

